#[derive(Clone, Copy, PartialEq)]
enum Quantity { ApparentSize, BlockSize, BlockCount }

#[derive(Clone, Copy, PartialEq)]
enum BytesFormat { Plain, Metric, Binary }

struct Config {
    json_input: bool,
    json_output: bool,
    bytes_format: BytesFormat,
    deduplicate_hardlinks: bool,
    top_down: bool,
    align_right: bool,
    quantity: Quantity,
    max_depth: Option<usize>,
    total_width: Option<usize>,
    column_width: Option<(usize, usize)>,
    min_ratio: f32,
    no_sort: bool,
    silent_errors: bool,
    progress: bool,
    threads: Option<usize>,
    omit_json_shared_details: bool,
    omit_json_shared_summary: bool,
    files: Vec<String>,
}

fn parse_args() -> Result<Config, String> {
    let mut config = Config {
        json_input: false,
        json_output: false,
        bytes_format: BytesFormat::Metric,
        deduplicate_hardlinks: false,
        top_down: false,
        align_right: false,
        quantity: Quantity::BlockSize,
        max_depth: Some(10),
        total_width: None,
        column_width: None,
        min_ratio: 0.01,
        no_sort: false,
        silent_errors: false,
        progress: false,
        threads: None,
        omit_json_shared_details: false,
        omit_json_shared_summary: false,
        files: Vec::new(),
    };

    let args: Vec<String> = env::args().skip(1).collect();
    let mut iter = args.iter().peekable();

    while let Some(arg) = iter.next() {
        if arg == "--json-input" { config.json_input = true; }
        else if arg == "--json-output" { config.json_output = true; }
        else if arg == "-b" || arg == "--bytes-format" {
            let val = iter.next().ok_or("Missing value for bytes-format")?;
            config.bytes_format = match val.as_str() {
                "plain" => BytesFormat::Plain,
                "metric" => BytesFormat::Metric,
                "binary" => BytesFormat::Binary,
                _ => return Err("Invalid bytes-format".to_string()),
            };
        } else if arg.starts_with("--bytes-format=") {
            let val = &arg[15..];
            config.bytes_format = match val {
                "plain" => BytesFormat::Plain,
                "metric" => BytesFormat::Metric,
                "binary" => BytesFormat::Binary,
                _ => return Err("Invalid bytes-format".to_string()),
            };
        }
        else if arg == "-H" || arg == "--deduplicate-hardlinks" || arg == "--detect-links" || arg == "--dedupe-links" {
            config.deduplicate_hardlinks = true;
        }
        else if arg == "--top-down" { config.top_down = true; }
        else if arg == "--align-right" { config.align_right = true; }
        else if arg == "-q" || arg == "--quantity" {
            let val = iter.next().ok_or("Missing value for quantity")?;
            config.quantity = match val.as_str() {
                "apparent-size" => Quantity::ApparentSize,
                "block-size" => Quantity::BlockSize,
                "block-count" => Quantity::BlockCount,
                _ => return Err("Invalid quantity".to_string()),
            };
        } else if arg.starts_with("--quantity=") {
            let val = &arg[11..];
            config.quantity = match val {
                "apparent-size" => Quantity::ApparentSize,
                "block-size" => Quantity::BlockSize,
                "block-count" => Quantity::BlockCount,
                _ => return Err("Invalid quantity".to_string()),
            };
        }
        else if arg == "-d" || arg == "--max-depth" || arg == "--depth" {
            let val = iter.next().ok_or("Missing value for max-depth")?;
            config.max_depth = if val == "inf" { None } else { Some(val.parse().map_err(|_| "Invalid depth")?) };
        } else if arg.starts_with("--max-depth=") {
            let val = &arg[12..];
            config.max_depth = if val == "inf" { None } else { Some(val.parse().map_err(|_| "Invalid depth")?) };
        } else if arg.starts_with("--depth=") {
            let val = &arg[8..];
            config.max_depth = if val == "inf" { None } else { Some(val.parse().map_err(|_| "Invalid depth")?) };
        }
        else if arg == "-w" || arg == "--total-width" || arg == "--width" {
            let val = iter.next().ok_or("Missing value for total-width")?;
            config.total_width = Some(val.parse().map_err(|_| "Invalid total-width")?);
        } else if arg.starts_with("--total-width=") {
            let val = &arg[14..];
            config.total_width = Some(val.parse().map_err(|_| "Invalid total-width")?);
        } else if arg.starts_with("--width=") {
            let val = &arg[8..];
            config.total_width = Some(val.parse().map_err(|_| "Invalid width")?);
        }
        else if arg == "--column-width" {
            let val1 = iter.next().ok_or("Missing TREE_WIDTH")?;
            let val2 = iter.next().ok_or("Missing BAR_WIDTH")?;
            config.column_width = Some((val1.parse().unwrap(), val2.parse().unwrap()));
        }
        else if arg == "-m" || arg == "--min-ratio" {
            let val = iter.next().ok_or("Missing value for min-ratio")?;
            config.min_ratio = val.parse().map_err(|_| "Invalid min-ratio")?;
        } else if arg.starts_with("--min-ratio=") {
            let val = &arg[12..];
            config.min_ratio = val.parse().map_err(|_| "Invalid min-ratio")?;
        }
        else if arg == "--no-sort" { config.no_sort = true; }
        else if arg == "-s" || arg == "--silent-errors" || arg == "--no-errors" { config.silent_errors = true; }
        else if arg == "-p" || arg == "--progress" { config.progress = true; }
        else if arg == "--threads" {
            let val = iter.next().ok_or("Missing threads")?;
            config.threads = if val == "auto" || val == "max" { None } else { Some(val.parse().unwrap()) };
        } else if arg.starts_with("--threads=") {
            let val = &arg[10..];
            config.threads = if val == "auto" || val == "max" { None } else { Some(val.parse().unwrap()) };
        }
        else if arg == "--omit-json-shared-details" { config.omit_json_shared_details = true; }
        else if arg == "--omit-json-shared-summary" { config.omit_json_shared_summary = true; }
        else if arg == "-h" || arg == "--help" {
            println!("Help goes here");
            std::process::exit(0);
        }
        else if arg == "-V" || arg == "--version" {
            println!("pdu 0.21.1");
            std::process::exit(0);
        }
        else if arg.starts_with("-") {
            return Err(format!("Unknown flag: {}", arg));
        }
        else {
            config.files.push(arg.clone());
        }
    }
    if config.files.is_empty() && !config.json_input {
        config.files.push(".".to_string());
    }
    Ok(config)
}

fn main() {
    let config = match parse_args() {
        Ok(c) => c,
        Err(e) => { eprintln!("{}", e); std::process::exit(1); }
    };
    println!("\n");
}
EOF
cargo build"}

