fn get_size(meta: &std::fs::Metadata, config: &Config) -> u64 {
    match config.quantity {
        Quantity::ApparentSize => meta.len(),
        Quantity::BlockSize => meta.blocks() * 512,
        Quantity::BlockCount => meta.blocks(),
    }
}

fn scan_dir(path: &Path, config: &Config, current_depth: usize, shared_map: &mut HashMap<(u64, u64), SharedInfo>) -> (Node, HashSet<(u64, u64)>) {
    let name = path.file_name().map(|n| n.to_string_lossy().into_owned()).unwrap_or_else(|| path.to_string_lossy().into_owned());
    let mut node = Node { name, size: 0, children: Vec::new() };
    let mut inos = HashSet::new();

    let meta = match fs::symlink_metadata(path) {
        Ok(m) => m,
        Err(e) => {
            if !config.silent_errors { eprintln!("pdu: {}: {}", path.display(), e); }
            return (node, inos);
        }
    };

    let size = get_size(&meta, config);
    node.size += size;

    if meta.is_dir() {
        if let Ok(entries) = fs::read_dir(path) {
            for entry in entries.flatten() {
                let (child_node, child_inos) = scan_dir(&entry.path(), config, current_depth + 1, shared_map);
                node.size += child_node.size;

                if config.deduplicate_hardlinks {
                    for ino in child_inos {
                        if !inos.insert(ino) {
                            if let Some(info) = shared_map.get(&ino) {
                                node.size -= info.size;
                            }
                        }
                    }
                }

                if current_depth < config.max_depth {
                    node.children.push(child_node);
                }
            }
        } else if !config.silent_errors {
            eprintln!("pdu: {}: Permission denied", path.display());
        }
    } else if config.deduplicate_hardlinks && meta.nlink() > 1 {
        let key = (meta.dev(), meta.ino());
        inos.insert(key);
        let info = shared_map.entry(key).or_insert(SharedInfo {
            size, links: meta.nlink(), paths: Vec::new()
        });
        info.paths.push(path.to_string_lossy().into_owned());
    }

    (node, inos)
}

fn filter_tree(node: &mut Node, root_size: u64, min_ratio: f32) {
    node.children.retain(|c| (c.size as f32 / root_size as f32) >= min_ratio);
    for c in &mut node.children {
        filter_tree(c, root_size, min_ratio);
    }
}

fn sort_tree(node: &mut Node) {
    node.children.sort_by_key(|c| c.size);
    for c in &mut node.children {
        sort_tree(c);
    }
}

fn format_size(size: u64, config: &Config) -> String {
    if config.quantity == Quantity::BlockCount || config.bytes_format == BytesFormat::Plain {
        return format!("{}", size);
    }
    let (div, units) = if config.bytes_format == BytesFormat::Metric {
        (1000.0, ["", "K", "M", "G", "T", "P", "E"])
    } else {
        (1024.0, ["", "K", "M", "G", "T", "P", "E"])
    };

    if (size as f32) < div {
        return format!("{}   ", size);
    }

    let mut v = size as f32;
    let mut u = 0;
    while v >= div && u < units.len() - 1 {
        v /= div;
        u += 1;
    }
    format!("{:.1}{}", v, units[u])
}

