                    json.push_str("\n");
                }
                json.push_str("        ]\n      }");
            }
            json.push_str("\n    ]");
        }
        if !config.omit_json_shared_summary {
            if !config.omit_json_shared_details { json.push_str(",\n"); }
            let inodes = shared_map.len();
