            json.push_str(&format!("      \"shared_size\": {},\n", shared_size));
            json.push_str(&format!("      \"exclusive_shared_size\": {}\n", exclusive_shared_size));
            json.push_str("    }\n");
        }
        json.push_str("  }\n");
    } else {
        json.push_str("\n");
    }
    json.push_str("}");
    println!("{}", json);
}

fn node_to_json(node: &Node, indent: usize) -> String {
    let ind = "  ".repeat(indent);
    let mut s = format!("{{\n{}\"name\": \"{}\",\n{}\"size\": {},\n{}\"children\": [", ind, node.name.replace("\"", "\\\""), ind, node.size, ind);
    if node.children.is_empty() {
        s.push_str("]\n");
        s.push_str(&"  ".repeat(indent - 1));
        s.push_str("}");
    } else {
        s.push_str("\n");
        for (i, c) in node.children.iter().enumerate() {
            s.push_str(&"  ".repeat(indent + 1));
            s.push_str(&node_to_json(c, indent + 2));
            if i < node.children.len() - 1 { s.push_str(","); }
            s.push_str("\n");
        }
        s.push_str(&ind);
        s.push_str("]\n");
        s.push_str(&"  ".repeat(indent - 1));
        s.push_str("}");
    }
    s
}

fn print_tree(root: &Node, config: &Config) {
    let mut flat = Vec::new();
    let mut max_str_len = 0;

    fn calc_max_len(node: &Node, config: &Config, max: &mut usize) {
        let l = format_size(node.size, config).len();
        if l > *max { *max = l; }
        for c in &node.children {
            calc_max_len(c, config, max);
        }
    }
    calc_max_len(root, config, &mut max_str_len);
    let size_col_width = max_str_len + 1;

    struct Line {
        full_left: String,
        pct: usize,
        w_d: usize,
        w_scaled: Vec<usize>,
    }
    let mut lines = Vec::new();

    fn build_lines(node: &Node, depth: usize, prefix: String, is_first: bool, is_last: bool, w: &mut Vec<usize>, config: &Config, root_size: u64, max_str_len: usize, lines: &mut Vec<Line>) {
        w.push((node.size as f64 / root_size as f64 * (config.total_width as f64)).round() as usize);

        let size_str = format_size(node.size, config);
        let aligned_size = format!("{:>width$} ", size_str, width = max_str_len);
        let pad = prefix.clone();

        let tree_char = if depth == 0 {
            if node.children.is_empty() { "┌──" } else { "┌─┴" }
        } else if is_first { 
            if node.children.is_empty() { "┌──" } else { "┌─┴" }
        } else if is_last {
            if node.children.is_empty() { "├──" } else { "├─┴" }
        } else {
            if node.children.is_empty() { "├──" } else { "├─┴" }
        };

        let tree_part = format!("{}{}{}", pad, tree_char, node.name);
        let mut full_left = format!("{}{}", aligned_size, tree_part);

        if let Some((t_w, _)) = config.column_width {
            let tree_limit = t_w;
            if tree_part.chars().count() > tree_limit {
                let allowed = tree_limit.saturating_sub(3);
                let t_str: String = tree_part.chars().take(allowed).collect();
                full_left = format!("{}{}{}...", aligned_size, t_str, "");
            }
        }

        let pct = if root_size == 0 { 0 } else { (node.size as f64 / root_size as f64 * 100.0).round() as usize };

        let mut w_scaled = vec![0; depth + 1];
        w_scaled.copy_from_slice(&w[0..=depth]); // Will scale later

        lines.push(Line { full_left, pct, w_d: w[depth], w_scaled });

        let child_count = node.children.len();
        for (i, c) in node.children.iter().enumerate() {
            let is_f = i == 0;
            let is_l = i == child_count - 1;
            let mut prefix_new = prefix.clone();
            prefix_new.push_str(if is_f { "  " } else { "│ " });
            build_lines(c, depth + 1, prefix_new, is_f, is_l, w, config, root_size, max_str_len, lines);
        }
        w.pop();
    }

    let mut w = Vec::new();
    build_lines(root, 0, String::new(), true, true, &mut w, config, root.size, max_str_len, &mut lines);

    let max_left_len = lines.iter().map(|l| l.full_left.chars().count()).max().unwrap_or(0);

    let bar_width = config.column_width.map(|x| x.1).unwrap_or_else(|| config.total_width.saturating_sub(max_left_len + 6).max(10));

    let char_for_depth = |d| if d == 1 { "░" } else if d == 2 { "▒" } else { "▓" };

    let mut flat = Vec::new();
    for mut l in lines {
        let left_len = l.full_left.chars().count();
        let left_padded = format!("{:<width$}", l.full_left, width = left_len + (max_left_len - left_len));

        for i in 0..l.w_scaled.len() {
            l.w_scaled[i] = (l.w_scaled[i] as f64 / config.total_width as f64 * bar_width as f64).round() as usize;
        }

        let depth = l.w_scaled.len() - 1;
        let mut bar = String::new();
        let w_d = l.w_scaled[depth];
        bar.push_str(&"█".repeat(w_d));

        let mut current_len = w_d;
        for i in (1..depth).rev() {
            let end_w = l.w_scaled[i];
            let len = end_w.saturating_sub(current_len);
            bar.push_str(&char_for_depth(i).repeat(len));
            current_len = end_w;
        }
        let space_len = bar_width.saturating_sub(current_len);

        let mut bar_pad = bar;
        if config.align_right {
            bar_pad = format!("{}{}", " ".repeat(space_len), bar_pad);
        } else {
            bar_pad = format!("{}{}", bar_pad, " ".repeat(space_len));
        }

        flat.push(format!("{}│{}│{:>3}%", left_padded, bar_pad, l.pct));
    }

    if config.top_down {
        for line in flat.into_iter() {
            println!("{}", line.replace("┌", "└").replace("┴", "┬"));
        }
    } else {
        for line in flat.into_iter().rev() {
            println!("{}", line);
        }
    }
}

// VERY SIMPLE JSON PARSER
fn parse_json_input(input: &str) -> Node {
    let start = input.find("\"tree\":").unwrap();
    let tree_str = &input[start..];
    fn parse_node(s: &str, mut idx: usize) -> (Node, usize) {
        let mut node = Node { name: String::new(), size: 0, children: Vec::new() };
        while idx < s.len() {
            if s[idx..].starts_with("\"name\"") {
                idx = s[idx..].find(':').unwrap() + idx + 1;
                while s.chars().nth(idx).unwrap().is_whitespace() || s.chars().nth(idx).unwrap() == '"' { idx += 1; }
                let end = s[idx..].find('"').unwrap() + idx;
                node.name = s[idx..end].to_string();
                idx = end + 1;
            } else if s[idx..].starts_with("\"size\"") {
                idx = s[idx..].find(':').unwrap() + idx + 1;
                while s.chars().nth(idx).unwrap().is_whitespace() { idx += 1; }
                let end = s[idx..].find(|c: char| !c.is_ascii_digit()).unwrap() + idx;
                node.size = s[idx..end].parse().unwrap();
                idx = end;
            } else if s[idx..].starts_with("\"children\"") {
                idx = s[idx..].find('[').unwrap() + idx + 1;
                while idx < s.len() {
                    while s.chars().nth(idx).unwrap().is_whitespace() || s.chars().nth(idx).unwrap() == ',' { idx += 1; }
                    if s.chars().nth(idx).unwrap() == ']' { idx += 1; break; }
                    if s.chars().nth(idx).unwrap() == '{' {
                        let (child, next_idx) = parse_node(s, idx + 1);
                        node.children.push(child);
                        idx = next_idx;
                    }
                }
            } else if s.chars().nth(idx).unwrap() == '}' {
                idx += 1;
                break;
            } else {
                idx += 1;
            }
        }
        (node, idx)
    }
    parse_node(tree_str, tree_str.find('{').unwrap() + 1).0
}

fn main() {
    let config = match parse_args() {
        Ok(c) => c,
        Err(e) => { eprintln!("{}", e); std::process::exit(1); }
    };

    let mut root;
    let mut shared_map = HashMap::new();

    if config.json_input {
        use std::io::Read;
        let mut input = String::new();
        std::io::stdin().read_to_string(&mut input).unwrap();
        root = parse_json_input(&input);
    } else {
        if config.files.len() == 1 {
            let (n, _) = scan_dir(Path::new(&config.files[0]), &config, 1, &mut shared_map);
            root = n;
        } else {
            root = Node { name: "(total)".to_string(), size: 0, children: Vec::new() };
            let mut total_inos = HashSet::new();
            for f in &config.files {
                let (n, inos) = scan_dir(Path::new(f), &config, 2, &mut shared_map);
                root.size += n.size;
                if config.deduplicate_hardlinks {
                    for ino in inos {
                        if !total_inos.insert(ino) {
                            if let Some(info) = shared_map.get(&ino) {
                                root.size -= info.size;
                            }
                        }
                    }
                }
                root.children.push(n);
            }
        }

        let root_size = root.size;
        filter_tree(&mut root, root_size, config.min_ratio);
        if !config.no_sort {
            sort_tree(&mut root);
        }
    }

    if config.json_output {
        println!("\n");
        print_json(&root, &shared_map, &config);
    } else {
        println!("\n");
        print_tree(&root, &config);

        if config.deduplicate_hardlinks && !shared_map.is_empty() {
            let inodes = shared_map.len();
            let exclusive_inodes = shared_map.values().filter(|i| i.paths.len() as u64 == i.links).count();
            let all_links: u64 = shared_map.values().map(|i| i.links).sum();
            let detected_links: u64 = shared_map.values().map(|i| i.paths.len() as u64).sum();
            let exclusive_links: u64 = shared_map.values().filter(|i| i.paths.len() as u64 == i.links).map(|i| i.links).sum();
            let shared_size: u64 = shared_map.values().map(|i| i.size).sum();
            let exclusive_shared_size: u64 = shared_map.values().filter(|i| i.paths.len() as u64 == i.links).map(|i| i.size).sum();

            if exclusive_inodes == 0 {
                println!("Hardlinks detected! All hardlinks within this tree have links without");
                println!("* Number of shared inodes: {}", inodes);
                println!("* Total number of links: {} total, {} detected", all_links, detected_links);
                let f_s = format_size(shared_size, &config).trim().to_string();
                println!("* Total shared size: {}", f_s);
            } else if exclusive_inodes == inodes {
                println!("Hardlinks detected! No files have links outside this tree");
                println!("* Number of shared inodes: {}", inodes);
                println!("* Total number of links: {}", all_links);
                let f_s = format_size(shared_size, &config).trim().to_string();
                println!("* Total shared size: {}", f_s);
            } else {
                println!("Hardlinks detected! Some files have links outside this tree");
                println!("* Number of shared inodes: {} total, {} exclusive", inodes, exclusive_inodes);
                println!("* Total number of links: {} total, {} detected, {} exclusive", all_links, detected_links, exclusive_links);
                let f_s = format_size(shared_size, &config).trim().to_string();
                let f_xs = format_size(exclusive_shared_size, &config).trim().to_string();
                println!("* Total shared size: {} total, {} exclusive", f_s, f_xs);
            }
        }
    }
}
